tape( 'the function sets rcond to 0.0 when D contains a non-positive element', function test( t ) {
	var rcond;
	var work;
	var out;
	var D;
	var E;

	// First element is non-positive
	D = new Float64Array( [ 0.0, 2.0, 1.0 ] );
	E = new Float64Array( [ 1.0, 1.0 ] );
	rcond = new Float64Array( [ 999.9 ] );
	work = new Float64Array( 3 );

	out = dptcon( 3, D, 1, 0, E, 1, 0, 3.0, rcond, 0, work, 1, 0 );
	t.strictEqual( out, 0, 'returns expected value' );
	t.strictEqual( rcond[ 0 ], 0.0, 'rcond is 0.0' );

	// Middle element is negative
	D = new Float64Array( [ 3.0, -2.0, 1.0 ] );
	E = new Float64Array( [ 1.0, 1.0 ] );
	rcond = new Float64Array( [ 999.9 ] );
	work = new Float64Array( 3 );

	out = dptcon( 3, D, 1, 0, E, 1, 0, 3.0, rcond, 0, work, 1, 0 );
	t.strictEqual( out, 0, 'returns expected value' );
	t.strictEqual( rcond[ 0 ], 0.0, 'rcond is 0.0' );

	// Last element is non-positive
	D = new Float64Array( [ 3.0, 2.0, 0.0 ] );
	E = new Float64Array( [ 1.0, 1.0 ] );
	rcond = new Float64Array( [ 999.9 ] );
	work = new Float64Array( 3 );

	out = dptcon( 3, D, 1, 0, E, 1, 0, 3.0, rcond, 0, work, 1, 0 );
	t.strictEqual( out, 0, 'returns expected value' );
	t.strictEqual( rcond[ 0 ], 0.0, 'rcond is 0.0' );

	t.end();
});

tape( 'the function computes the reciprocal of the condition number for N=1', function test( t ) {
	var rcond;
	var work;
	var out;
	var D;
	var E;

	D = new Float64Array( [ 4.0 ] );
	E = new Float64Array( [] );
	rcond = new Float64Array( 1 );
	work = new Float64Array( 1 );

	out = dptcon( 1, D, 1, 0, E, 1, 0, 4.0, rcond, 0, work, 1, 0 );
	t.strictEqual( out, 0, 'returns expected value' );
	t.strictEqual( rcond[ 0 ], 1.0, 'rcond is 1.0 for 1x1 identity-like matrix' );
	t.strictEqual( work[ 0 ], 0.25, 'work contains expected value' );
	t.end();
});

