tape( 'the function supports providing negative strides', function test( t ) {
	var rcond;
	var work;
	var out;
	var D;
	var E;

	// D accessed backward: D[4], D[2], D[0] -> logical [3.0, 2.0, 1.0]
	// E accessed backward: E[2], E[0] -> logical [1.0, 1.0]
	D = new Float64Array( [ 1.0, 0.0, 2.0, 0.0, 3.0 ] );
	E = new Float64Array( [ 1.0, 0.0, 1.0 ] );
	rcond = new Float64Array( 1 );
	work = new Float64Array( 3 );

	out = dptcon( 3, D, -2, 4, E, -2, 2, 3.0, rcond, 0, work, 1, 0 );
	t.strictEqual( out, 0, 'returns expected value' );
	isApprox( t, rcond, new Float64Array( [ 0.07692307692307693 ] ), 2.0 );
	t.end();
});

